from scipy.optimize import least_squares
import warnings; warnings.filterwarnings('ignore')
a=df['dv_dt'].values; t=df['t'].values; x=df['x'].values; v=df['v'].values
fams={
'F1':lambda p: p[0]*np.exp(-p[1]*x**2)+p[2]*x+p[3]*v+p[4]*t*v+p[5]*v*np.abs(v),
'F2':lambda p: p[0]*np.exp(-p[1]*x**2)+p[2]*v*np.cos(p[3]*t)+p[4]*x**3+p[5]*v,
'F3':lambda p: p[0]*np.exp(-p[1]*x**2)+p[2]*x*np.sin(p[3]*t)+p[4]*v+p[5]*v**3,
'F4':lambda p: p[0]*np.exp(-p[1]*x**2)+p[2]*t*v+p[3]*v**3+p[4]*x+p[5]*t,
'F5':lambda p: p[0]*np.exp(-p[1]*x**2)+p[2]*np.cos(p[3]*t)*v+p[4]*x*v+p[5]*v**2,
'F6':lambda p: p[0]*np.exp(-p[1]*x**2)+p[2]*np.sin(p[3]*t)+p[4]*v+p[5]*x**3,
}
rng=np.random.default_rng(1)
for fn,f in fams.items():
    best=None
    for k in range(80):
        p0=rng.normal(size=6)*1.5
        try:
            r=least_squares(lambda p: f(p)-a, p0)
            if np.all(np.isfinite(r.fun)) and (best is None or r.cost<best.cost): best=r
        except Exception: pass
    if best is not None: print(fn, np.mean((f(best.x)-a)**2)/np.var(a), np.round(best.x,4))
